/// Fictional output generated by producer #588 at 07d3b48b; no runtime input.
/// Shared by XCTest and the standalone fixture on hosts without XCTest.
enum QuotaProvenanceFixture {
    static let json = #"{"accountQuotas":{"state":"available","complete":true,"accounts":[{"label":"Example codex","provider":"codex","summary":{"provenance":{"version":1,"retrievedAt":"2030-03-04T12:00:00Z","providerObservedAt":null},"state":"reported","text":"No recognized quota meters were reported.","source":"codex account/rateLimits/read","observedAt":"2030-03-04T12:00:00Z","freshness":"fresh","rows":[{"name":"Provider availability","text":"Unknown; percentages and reset times do not establish access."}],"partial":true}},{"label":"Example claude-code","provider":"claude-code","summary":{"provenance":{"version":1,"retrievedAt":"2030-03-04T12:00:00Z","providerObservedAt":null},"state":"reported","text":"No recognized quota meters were reported.","source":"claude:get_usage","retrievedAt":"2030-03-04T12:00:00Z","freshness":"provider_unknown","rows":[{"name":"Provider availability","text":"Unknown; percentages and reset times do not establish access."}],"partial":true}},{"label":"Example antigravity","provider":"antigravity","summary":{"provenance":{"version":1,"retrievedAt":"2030-03-04T12:00:00Z","providerObservedAt":null},"state":"reported","text":"No recognized quota meters were reported.","source":"agy:/usage","retrievedAt":"2030-03-04T12:00:00Z","freshness":"provider_unknown","rows":[{"name":"Provider availability","text":"Unknown; percentages and reset times do not establish access."}],"partial":true}}],"omitted":0},"schemaVersion":1,"readAt":"2030-03-04T12:00:00Z","registry":"available","complete":true,"allClear":true,"needsYou":0,"unread":0,"omitted":0,"loops":[],"archived":0,"notices":null,"canAll":null}"#
    struct Failure: Error { let text: String }
    static func require(_ condition: Bool, _ message: String) throws {
        if !condition { throw Failure(text: message) }
    }
    static func rawDuplicateKeys(_ input: Data) throws {
        let raw = String(decoding: input, as: UTF8.self)
        func replacing(_ text: String, _ token: String, _ replacement: String) throws -> Data {
            guard let range = text.range(of: token) else { throw Failure(text: "Raw fixture token absent: " + token) }
            var changed = text
            changed.replaceSubrange(range, with: replacement)
            return Data(changed.utf8)
        }
        var acceptedDuplicates: [String] = []
        func rejected(_ bytes: Data, _ name: String) throws {
            // Validate fixture syntax without using the normalized object for the test.
            _ = try JSONSerialization.jsonObject(with: bytes)
            do { _ = try Contract.panelList(bytes, exit: 0) } catch { return }
            acceptedDuplicates.append(name)
        }
        let stamp = #""2030-03-04T12:00:00Z""#
        for (key, escaped, valid, invalid) in [
            ("version", #"\u0076ersion"#, "1", "2"),
            ("retrievedAt", #"\u0072etrievedAt"#, stamp, #""2031-03-04T12:00:00Z""#),
            ("providerObservedAt", #"\u0070roviderObservedAt"#, "null", stamp)
        ] {
            let token = "\"" + key + "\":" + valid
            for (first, second) in [(valid, invalid), (invalid, valid), (valid, valid), (invalid, invalid)] {
                for (left, right) in [(key, key), (key, escaped), (escaped, key)] {
                    let duplicate = "\"" + left + "\":" + first + ",\"" + right + "\":" + second
                    try rejected(replacing(raw, token, duplicate), key + " " + duplicate)
                }
            }
            // Escapes alone are legitimate JSON and do not manufacture duplicates.
            _ = try Contract.panelList(replacing(raw, token, "\"" + escaped + "\":" + valid), exit: 0)
        }
        let object = #"{"version":1,"retrievedAt":"2030-03-04T12:00:00Z","providerObservedAt":null}"#
        for (first, second) in [(object, "null"), ("null", object), (object, object)] {
            for key in ["provenance", #"\u0070rovenance"#] {
                try rejected(replacing(raw, "\"provenance\":" + object, "\"provenance\":" + first + ",\"" + key + "\":" + second), "duplicate summary.provenance")
            }
        }
        // Enclosing duplicate keys cannot hide an ambiguous provenance path.
        for token in ["\"accountQuotas\":{", "\"accounts\":[", "\"summary\":{"] {
            let key = String(token.dropLast())
            try rejected(replacing(raw, token, key + "null," + token), "duplicate enclosing " + token)
            let changed = try replacing(raw, token, key + "null," + token)
            // Reverse null/object order using the complete valid value below.
            let parsed = try JSONSerialization.jsonObject(with: input) as! [String: Any]
            let quotas = parsed["accountQuotas"] as! [String: Any]
            let accounts = quotas["accounts"] as! [[String: Any]]
            let value: Any = token.contains("accountQuotas") ? quotas : token.contains("accounts") ? accounts : accounts[0]["summary"]!
            let encoded = String(decoding: try JSONSerialization.data(withJSONObject: value, options: [.sortedKeys]), as: UTF8.self)
            try rejected(replacing(String(decoding: changed, as: UTF8.self), key + "null,", key + encoded + ","), "duplicate equal enclosing " + token)
            try rejected(replacing(raw, token, key + encoded + "," + key + "null,\"ignoredFixture\":" + String(token.suffix(1))), "duplicate reversed enclosing " + token)
        }
        var escapedPath = raw
        for (key, escaped) in [("accountQuotas", #"\u0061ccountQuotas"#), ("accounts", #"\u0061ccounts"#), ("summary", #"\u0073ummary"#), ("provenance", #"\u0070rovenance"#)] {
            escapedPath = escapedPath.replacingOccurrences(of: "\"" + key + "\":", with: "\"" + escaped + "\":")
        }
        _ = try Contract.panelList(Data(escapedPath.utf8), exit: 0)
        // Scope stays additive: old producers and unrelated ignored fields are
        // still accepted, including strings that merely resemble duplicate keys.
        let legacy = raw.replacingOccurrences(of: "\"provenance\":" + object + ",", with: "")
        _ = try Contract.panelList(Data(legacy.utf8), exit: 0)
        _ = try Contract.panelList(Data([0xEF, 0xBB, 0xBF]) + Data(legacy.utf8), exit: 0)
        _ = try Contract.panelList(replacing(legacy, "{", #"{"ignoredFixture":{"version":1,"version":2,"text":"escaped \"version\":1,\"version\":2"},"#), exit: 0)
        try require(acceptedDuplicates.isEmpty, "Accepted raw duplicate keys (\(acceptedDuplicates.count)): " + acceptedDuplicates.joined(separator: "; "))
    }
    static func run(_ input: Data = Data(json.utf8)) throws {
        try rawDuplicateKeys(input)
        let now = Contract.date("2030-03-04T12:00:00Z")!
        let original = try JSONSerialization.jsonObject(with: input) as! [String: Any]
        let quotas = original["accountQuotas"] as! [String: Any]
        let accounts = quotas["accounts"] as! [[String: Any]]
        let decoded = try Contract.panelList(input, exit: 0)
        try require(decoded.accountQuotas?.accounts.map(\.provider) == ["codex", "claude-code", "antigravity"], "Three actual producer sources required")
        func payload(_ i: Int, _ edit: (inout [String: Any]) -> Void) throws -> Data {
            var object = original, q = quotas, entries = accounts
            var summary = entries[i]["summary"] as! [String: Any]
            edit(&summary)
            entries[i]["summary"] = summary; q["accounts"] = entries; object["accountQuotas"] = q
            return try JSONSerialization.data(withJSONObject: object)
        }
        func rejected(_ data: Data, _ message: String) throws {
            do { _ = try Contract.panelList(data, exit: 0) } catch { return }
            throw Failure(text: "Accepted invalid provenance: " + message)
        }
        for i in accounts.indices {
            let a = decoded.accountQuotas!.accounts[i]
            try require(a.summary.provenance?.version == 1 && a.summary.provenance?.providerObservedAt == nil, "Explicit v1 unknown")
            for data in [input, try payload(i) { $0.removeValue(forKey: "provenance") }] {
                let account = try Contract.panelList(data, exit: 0).accountQuotas!.accounts[i]
                let row = MenuBuilder.quotaAccountRow(account, now: now)
                try require(MenuBuilder.quotaAge(account.summary, now: now).contains("provider freshness unknown"), "Recent fetch became provider freshness")
                try require(row.submenu.contains { $0.accessibilityLabel.contains("Provider observation time unavailable") }, "Missing unknown provider time")
                try require(row.submenu.contains { $0.accessibilityLabel.contains("2030-03-04T12:00:00Z (local retrieval time)") }, "Wrong retained local time")
                try require(MenuBuilder.quotaAge(account.summary, now: now.addingTimeInterval(1801)).contains("older reading"), "Age did not advance")
                try require(MenuBuilder.quotaAge(account.summary, now: now.addingTimeInterval(-1)).contains("device clock"), "Future retrieval accepted as recent")
                try require(row.submenu.compactMap(\.command) == [.openPanel], "New action authority")
            }
            let good = (accounts[i]["summary"] as! [String: Any])["provenance"] as! [String: Any]
            var invalid: [(String, Any)] = [("null", NSNull()), ("string", "v1"), ("array", []), ("empty", [String: Any]())]
            for key in ["version", "retrievedAt", "providerObservedAt"] {
                var p = good; p.removeValue(forKey: key); invalid.append(("missing " + key, p))
            }
            for (key, value) in [("version", 2 as Any), ("version", true), ("version", "1"), ("retrievedAt", NSNull()), ("retrievedAt", "invalid"), ("retrievedAt", "2030-03-04T12:00:00Zgarbage"), ("retrievedAt", "2030-02-31T12:00:00Z"), ("retrievedAt", "2030-03-04T12:00:00Z\n"), ("retrievedAt", "2030-03-04T12:00:01Z"), ("retrievedAt", "2030-03-04T12:00:00.000000001Z"), ("providerObservedAt", "2030-03-04T12:00:00Z"), ("providerObservedAt", false), ("extra", "unknown"), ("Version", 1)] {
                var p = good; p[key] = value; invalid.append(("invalid " + key + " " + String(describing: value), p))
            }
            for (name, bad) in invalid { try rejected(payload(i) { $0["provenance"] = bad }, name) }
            // New metadata cannot override legacy source, provider or time contracts.
            for field in ["source", "freshness"] {
                try rejected(payload(i) { $0[field] = "unsupported" }, field)
            }
            try rejected(payload(i) { $0["observedAt"] = "2030-03-04T12:00:00Z"; $0["retrievedAt"] = "2030-03-04T12:00:00Z" }, "conflicting legacy timestamps")
            try rejected(payload(i) { $0["state"] = "unavailable"; $0["freshness"] = "unavailable"; $0.removeValue(forKey: "source"); $0.removeValue(forKey: "observedAt"); $0.removeValue(forKey: "retrievedAt"); $0["rows"] = [] }, "provenance on unavailable record")
            // Equal instants with different offsets are not a time mismatch.
            _ = try Contract.panelList(payload(i) { var p = good; p["retrievedAt"] = "2030-03-04T13:00:00+01:00"; $0["provenance"] = p }, exit: 0)
            _ = try Contract.panelList(payload(i) { var p = good; p["retrievedAt"] = "2030-03-04T12:00:00.000000000Z"; $0["provenance"] = p }, exit: 0)
            _ = try Contract.panelList(payload(i) {
                var p = good; p["retrievedAt"] = "2030-03-04T12:00:00.123456789Z"; $0["provenance"] = p
                $0[i == 0 ? "observedAt" : "retrievedAt"] = "2030-03-04T12:00:00.123456789Z"
            }, exit: 0)
        }
        let exhausted = try payload(0) {
            $0["rows"] = [["name": "5-hour", "text": "100% used · 0% remaining", "usedPercent": 100, "remainingPercent": 0, "resetsAt": "2030-03-04T13:00:00Z"]]
            $0["failedRefreshAt"] = "2030-03-04T12:05:00Z"
            $0["failedRefreshText"] = "Timed out; retained evidence unchanged."
        }
        let account = try Contract.panelList(exhausted, exit: 0).accountQuotas!.accounts[0]
        let before = MenuBuilder.quotaAccountRow(account, now: now)
        let after = MenuBuilder.quotaAccountRow(account, now: now.addingTimeInterval(3600))
        try require(before.detail.contains("0.0% left"), "Exhaustion lost")
        try require(after.detail == "Reading out of date" && !after.detail.contains("100.0% left"), "Reset restored capacity")
        try require(after.submenu.contains { $0.accessibilityLabel.contains("Refresh failed 2030-03-04T12:05:00Z") }, "Failed attempt lost")
        try require(account.summary.localRetrievedAt == "2030-03-04T12:00:00Z", "Failure rewrote success")
        try require(before.submenu.compactMap(\.command) == after.submenu.compactMap(\.command), "Reset changed targets")
    }
}
